:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52d5;
  --success: #4caf50;
  --fail: #e57373;
  --border: #44445a;
  --radius: 10px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 4px;
  color: var(--accent);
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b8;
  margin-bottom: 24px;
}

.input-group {
  margin-bottom: 16px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 1rem;
}

input[type="text"] {
  width: 100%;
  padding: 12px 16px;
  font-size: 1rem;
  font-family: var(--font);
  background: #1e1e2f;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="text"]:hover {
  border-color: var(--accent);
}

input[type="text"]:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.4);
}

button {
  display: block;
  width: 100%;
  padding: 14px;
  font-size: 1.125rem;
  font-weight: 700;
  font-family: var(--font);
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  margin-top: 8px;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.98);
}

.result {
  margin: 24px 0;
  padding: 16px;
  border-radius: var(--radius);
  background: #1e1e2f;
  border-left: 6px solid var(--border);
  min-height: 3.5rem;
  display: flex;
  align-items: center;
}

.result.anagram {
  border-left-color: var(--success);
}

.result.not-anagram {
  border-left-color: var(--fail);
}

.result p {
  font-size: 1.125rem;
  font-weight: 600;
}

.history-section h2 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.history-list {
  list-style: none;
  padding: 0;
}

.history-list li {
  padding: 10px 12px;
  margin-bottom: 8px;
  border-radius: var(--radius);
  background: #1e1e2f;
  border-left: 4px solid var(--border);
  font-size: 0.95rem;
  word-break: break-word;
}

.history-list li.anagram {
  border-left-color: var(--success);
}

.history-list li.not-anagram {
  border-left-color: var(--fail);
}

.history-list li.empty {
  color: #8888a0;
  font-style: italic;
  border-left-color: transparent;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
}

const input1 = document.getElementById('input1');
const input2 = document.getElementById('input2');
const checkBtn = document.getElementById('checkBtn');
const resultSection = document.getElementById('result');
const resultText = document.getElementById('resultText');
const historyList = document.getElementById('historyList');

const MAX_HISTORY = 5;
let history = [];

function normalize(str) {
  return str.replace(/\s+/g, '').toLowerCase();
}

function isAnagram(a, b) {
  const na = normalize(a);
  const nb = normalize(b);
  if (na === '' || nb === '') return null;
  return na.split('').sort().join('') === nb.split('').sort().join('');
}

function renderResult(anagram, a, b) {
  resultSection.classList.remove('anagram', 'not-anagram');
  if (anagram === null) {
    resultText.textContent = 'Please enter text in both boxes.';
    return;
  }
  if (anagram) {
    resultSection.classList.add('anagram');
    resultText.textContent = `"${a}" and "${b}" are anagrams.`;
  } else {
    resultSection.classList.add('not-anagram');
    resultText.textContent = `"${a}" and "${b}" are not anagrams.`;
  }
}

function renderHistory() {
  historyList.innerHTML = '';
  if (history.length === 0) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent = 'No checks yet.';
    historyList.appendChild(li);
    return;
  }
  for (const entry of history) {
    const li = document.createElement('li');
    li.className = entry.anagram ? 'anagram' : 'not-anagram';
    const status = entry.anagram ? 'Anagram' : 'Not anagram';
    li.textContent = `${status}: "${entry.a}" / "${entry.b}"`;
    historyList.appendChild(li);
  }
}

function check() {
  const a = input1.value.trim();
  const b = input2.value.trim();
  const anagram = isAnagram(a, b);
  renderResult(anagram, a, b);
  if (anagram !== null) {
    history.unshift({ a, b, anagram });
    if (history.length > MAX_HISTORY) history.pop();
    renderHistory();
  }
}

checkBtn.addEventListener('click', check);

[input1, input2].forEach(el => {
  el.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      e.preventDefault();
      check();
    }
  });
});
